// Database connection, schema, seed data and promise-based helpers.
const sqlite3 = require('sqlite3');
const { hashPassword } = require('../utils/password');
const { PAYMENT_STATUS, COURSE_ACTIVE } = require('../config/constants');

const SCHEMA = [
    'PRAGMA foreign_keys = ON',
    'CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT, email TEXT, pass TEXT)',
    'CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY, title TEXT, price REAL, active INTEGER)',
    `CREATE TABLE IF NOT EXISTS enrollments (
        id INTEGER PRIMARY KEY,
        user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
        course_id INTEGER REFERENCES courses(id) ON DELETE CASCADE
    )`,
    `CREATE TABLE IF NOT EXISTS payments (
        id INTEGER PRIMARY KEY,
        enrollment_id INTEGER REFERENCES enrollments(id) ON DELETE CASCADE,
        amount REAL,
        status TEXT
    )`,
    'CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, action TEXT, created_at DATETIME)',
];

function run(db, sql, params = []) {
    return new Promise((resolve, reject) => {
        db.run(sql, params, function onRun(err) {
            if (err) return reject(err);
            resolve({ lastID: this.lastID, changes: this.changes });
        });
    });
}

function get(db, sql, params = []) {
    return new Promise((resolve, reject) => {
        db.get(sql, params, (err, row) => (err ? reject(err) : resolve(row)));
    });
}

function all(db, sql, params = []) {
    return new Promise((resolve, reject) => {
        db.all(sql, params, (err, rows) => (err ? reject(err) : resolve(rows)));
    });
}

function open(path) {
    return new Promise((resolve, reject) => {
        const db = new sqlite3.Database(path, (err) => (err ? reject(err) : resolve(db)));
    });
}

async function seed(db) {
    const existing = await get(db, 'SELECT COUNT(*) AS total FROM users');
    if (existing.total > 0) return;
    await run(db, 'INSERT INTO users (name, email, pass) VALUES (?, ?, ?)',
        ['Leonan', 'leonan@fullcycle.com.br', hashPassword('123')]);
    await run(db, 'INSERT INTO courses (title, price, active) VALUES (?, ?, ?), (?, ?, ?)',
        ['Clean Architecture', 997.0, COURSE_ACTIVE, 'Docker', 497.0, COURSE_ACTIVE]);
    await run(db, 'INSERT INTO enrollments (user_id, course_id) VALUES (?, ?)', [1, 1]);
    await run(db, 'INSERT INTO payments (enrollment_id, amount, status) VALUES (?, ?, ?)',
        [1, 997.0, PAYMENT_STATUS.PAID]);
}

/**
 * Opens the database, creates the schema and seeds it.
 * Returns a handle with run/get/all helpers and a serialized transaction helper
 * (a single sqlite connection cannot run two transactions at once).
 */
async function createDatabase({ databasePath }) {
    const db = await open(databasePath);
    for (const statement of SCHEMA) {
        await run(db, statement);
    }
    await seed(db);

    let queue = Promise.resolve();
    const inTransaction = (work) => {
        const result = queue.then(async () => {
            await run(db, 'BEGIN');
            try {
                const output = await work();
                await run(db, 'COMMIT');
                return output;
            } catch (err) {
                await run(db, 'ROLLBACK');
                throw err;
            }
        });
        queue = result.catch(() => {});
        return result;
    };

    return {
        run: (sql, params) => run(db, sql, params),
        get: (sql, params) => get(db, sql, params),
        all: (sql, params) => all(db, sql, params),
        inTransaction,
        close: () => new Promise((resolve) => db.close(() => resolve())),
    };
}

module.exports = { createDatabase };

