const { hashPassword } = require('../utils/password');

function createUserModel(db) {
    return {
        findByEmail(email) {
            return db.get('SELECT id, name, email FROM users WHERE email = ?', [email]);
        },

        // password is optional: without it the account has no usable password (NULL), never a default one.
        async create({ name, email, password }) {
            const passwordHash = password ? hashPassword(password) : null;
            const { lastID } = await db.run(
                'INSERT INTO users (name, email, pass) VALUES (?, ?, ?)', [name, email, passwordHash]);
            return { id: lastID, name, email };
        },

        // Enrollments and payments are removed by ON DELETE CASCADE in the same statement.
        async deleteById(id) {
            const { changes } = await db.run('DELETE FROM users WHERE id = ?', [id]);
            return changes > 0;
        },
    };
}

module.exports = { createUserModel };

