// Persistence for the courses table, including the revenue rows used by the financial report.
const { COURSE_ACTIVE } = require('../config/constants');

function createCourseModel(db) {
    return {
        findActiveById(id) {
            return db.get('SELECT * FROM courses WHERE id = ? AND active = ?', [id, COURSE_ACTIVE]);
        },

        // One row per (course, enrollment); courses without enrollments come back with NULL columns.
        findRevenueRows() {
            return db.all(`
                SELECT c.id AS course_id, c.title, e.id AS enrollment_id,
                       u.name AS student_name, p.amount, p.status
                FROM courses c
                LEFT JOIN enrollments e ON e.course_id = c.id
                LEFT JOIN users u ON u.id = e.user_id
                LEFT JOIN payments p ON p.enrollment_id = e.id
                ORDER BY c.id, e.id`);
        },
    };
}

module.exports = { createCourseModel };

