// Checkout use case: validate course, charge the card, then enroll atomically.
const { PAYMENT_STATUS } = require('../config/constants');
const { badRequest, notFound } = require('../utils/httpError');

function createCheckoutService({ db, models, paymentGateway, logger }) {
    const { userModel, courseModel, enrollmentModel, paymentModel, auditLogModel } = models;

    return {
        async checkout({ name, email, password, courseId, cardNumber }) {
            const course = await courseModel.findActiveById(courseId);
            if (!course) throw notFound('Curso não encontrado');

            const status = paymentGateway.charge(cardNumber, course.price);
            if (status === PAYMENT_STATUS.DENIED) throw badRequest('Pagamento recusado');

            const enrollment = await db.inTransaction(async () => {
                const user = (await userModel.findByEmail(email))
                    || (await userModel.create({ name, email, password }));
                const created = await enrollmentModel.create(user.id, course.id);
                await paymentModel.create(created.id, course.price, status);
                await auditLogModel.record(`Checkout curso ${course.id} por ${user.id}`);
                return created;
            });

            logger.info('Checkout completed', { enrollmentId: enrollment.id, courseId: course.id });
            return { enrollmentId: enrollment.id };
        },
    };
}

module.exports = { createCheckoutService };

