// POST /api/checkout: validates the request body and delegates to the checkout service.
// Public body field names (usr, eml, pwd, c_id, card) are kept for API compatibility.
const { badRequest } = require('../utils/httpError');

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const isNonEmptyString = (value) => typeof value === 'string' && value.trim() !== '';

function parseCheckoutBody(body = {}) {
    const { usr: name, eml: email, pwd: password, c_id: courseId, card: cardNumber } = body;

    if (!name || !email || !courseId || !cardNumber) throw badRequest();
    if (!isNonEmptyString(name) || !isNonEmptyString(cardNumber)) throw badRequest();
    if (!isNonEmptyString(email) || !EMAIL_PATTERN.test(email)) throw badRequest();
    if (password !== undefined && password !== null && typeof password !== 'string') throw badRequest();

    return { name, email, password: password || null, courseId, cardNumber };
}

function createCheckoutController({ checkoutService }) {
    return {
        async checkout(req, res) {
            const input = parseCheckoutBody(req.body);
            const { enrollmentId } = await checkoutService.checkout(input);
            res.status(200).json({ msg: 'Sucesso', enrollment_id: enrollmentId });
        },
    };
}

module.exports = { createCheckoutController };

