// Guards privileged routes with the X-Admin-Token header (constant-time comparison).
const crypto = require('crypto');
const { forbidden, unauthorized } = require('../utils/httpError');

function requireAdmin({ adminToken }) {
    return (req, res, next) => {
        if (!adminToken) return next(forbidden('Endpoint desabilitado'));
        const supplied = Buffer.from(req.get('X-Admin-Token') || '');
        const expected = Buffer.from(adminToken);
        if (supplied.length !== expected.length || !crypto.timingSafeEqual(supplied, expected)) {
            return next(unauthorized('Token de administrador obrigatório'));
        }
        next();
    };
}

module.exports = { requireAdmin };

