// Entry point / composition root: load config, open the database, wire layers, start the server.
const express = require('express');
const config = require('./config');
const { createLogger } = require('./utils/logger');
const { createDatabase } = require('./database/connection');
const { buildModels } = require('./models');
const { buildServices } = require('./services');
const { buildControllers } = require('./controllers');
const { buildRoutes } = require('./routes');
const { requireAdmin } = require('./middlewares/requireAdmin');
const { createErrorHandler } = require('./middlewares/errorHandler');

async function main() {
    const logger = createLogger(config.logLevel);
    const db = await createDatabase(config);
    const models = buildModels(db);
    const services = buildServices({ db, models, config, logger });
    const controllers = buildControllers({ services, models });

    const app = express();
    app.use(express.json());
    app.use(buildRoutes(controllers, requireAdmin(config)));
    app.use(createErrorHandler({ logger }));

    app.listen(config.port, () => {
        logger.info(`Frankenstein LMS rodando na porta ${config.port}...`);
        if (!config.adminToken) logger.warn('ADMIN_TOKEN not set: admin endpoints are disabled (403)');
    });
}

main().catch((err) => {
    console.error('Failed to start application:', err);
    process.exit(1);
});

